from research_helpers import *
a=ev('https://vikingtherapeutics.com/pipeline/overview/','Current issuer pipeline lists five molecules with separate oral/subcutaneous VK2735 formulations; maintenance studies not separate products.')
b=ev('https://vikingtherapeutics.com/pipeline/vk5211/','Issuer describes oral SARM development and completed hip-fracture Phase2 study.')
c=ev('https://vikingtherapeutics.com/pipeline/vk3019/','Issuer identifies investigational amylin receptor agonist and filed IND; planned trial dates not treated as completed.')
products=[p(n,d,a,life='development',evidence=[a]+([b] if n=='VK5211' else [c] if n=='VK3019' else [])) for n,d in [('VK2735 subcutaneous','Investigational injectable dual GLP-1/GIP agonist for obesity.'),('VK2735 oral','Investigational oral formulation of dual GLP-1/GIP agonist for obesity.'),('VK3019','Investigational amylin receptor agonist for obesity.'),('VK2809','Investigational thyroid-hormone-receptor beta agonist for MASH.'),('VK0214','Investigational thyroid-hormone-receptor beta agonist for X-linked adrenoleukodystrophy.'),('VK5211','Investigational oral selective androgen receptor modulator for muscle preservation and hip-fracture recovery.')]]
co=dict(company_id='cmp_36da30e7-63e0-4e42-8858-ca61cbb12d36',products=products,evidence=[a,b,c],status='partial',coverage_note='Current named pipeline covered at molecule/formulation level: six records. Partial: legacy DGAT1/EPOR programmes, Ligand development-code aliases/licensing and historical formulations remain to review. No duplication for trials or maintenance indications. All investigational; no forecasted trial phases asserted as achieved.')
(out/'batch-0433.json').write_text(json.dumps({'companies':[co]},indent=2))
a=ev('https://cytomx.com/pipeline/','Current pipeline identifies Varseta-M/CX2051, CX801, CX908 and Probody platform; unnamed partner programmes and combination trials not duplicated.')
products=[p('Varseta-M','Investigational EpCAM-targeting antibody-drug conjugate for solid tumors.',a,life='development',aliases=['CX-2051']),p('CX-801','Investigational interferon-alpha-2b Probody cytokine for cancer.',a,life='development'),p('CX-908','Preclinical P-cadherin/CD3 T-cell engager programme for solid tumors.',a,life='research'),p('Probody therapeutic platform','Conditionally activated biologic therapeutics technology platform.',a,life='development',typ='technology')]
co=dict(company_id='cmp_36afb58f-db44-481f-8034-12a7a55f44aa',products=products,evidence=[a],status='partial',coverage_note='Three current named candidates and Probody platform. Partial: historical CX072/CX2009/CX2029/CX904, BMS programmes, other partnered candidates and updated aliases/dispositions require review. Bevacizumab/chemotherapy combinations treated as trial context; not owned single-agent products. Undisclosed partner targets not invented.')
(out/'batch-0434.json').write_text(json.dumps({'companies':[co]},indent=2))
